export const VERSION='demo-2026-10-12.1';
export const sources={warfarin:'https://www.nhs.uk/medicines/warfarin/',methotrexate:'https://www.nhs.uk/medicines/methotrexate/taking-methotrexate-with-other-medicines-and-herbal-supplements/',weekly:'https://www.nhs.uk/medicines/methotrexate/how-and-when-to-take-methotrexate/',paracetamol:'https://www.fda.gov/drugs/safe-use-over-counter-pain-relievers-and-fever-reducers/acetaminophen',nsaid:'https://www.nhs.uk/medicines/nsaids/',ramipril:'https://www.nhs.uk/medicines/ramipril/taking-ramipril-with-other-medicines-and-herbal-supplements/'};
export const catalog=['paracetamol','ibuprofen','aspirin','naproxen','warfarin','methotrexate','trimethoprim','co-trimoxazole','ramipril','spironolactone'];
export const normalize=s=>String(s||'').trim().toLowerCase().replace(/^acetaminophen$/,'paracetamol');
export function analyze(medicines,c={}){
 const findings=[],gaps=['This small rule set cannot check every interaction or confirm that a prescription is safe.','No trained AI model, laboratory interpretation, pregnancy dosing, or complete dose database is connected.'];
 const active=medicines.filter(m=>m.status==='current'),names=active.map(m=>normalize(m.name)),nsaids=['ibuprofen','aspirin','naproxen'];
 const add=(id,level,title,explanation,trigger,source)=>findings.push({id,level,title,explanation,trigger,source,action:'Ask your pharmacist or prescribing doctor to review this. Do not change your treatment on your own.'});
 if(!c.age||Number(c.age)<18) gaps.push('Adult age is missing or the person is under 18. Child-specific checks are not supported.');
 if(!['known','none'].includes(c.allergyStatus))gaps.push('Allergy history is unknown. Allergy checking is incomplete.');
 if(!c.historyConfirmed)gaps.push('Health-condition history has not been confirmed.');
 if(!active.length)gaps.push('No current medicines were entered.');
 for(const m of active){const n=normalize(m.name);
 if(!catalog.includes(n))gaps.push(`${m.name||'Unnamed medicine'}: unsupported ingredient. Combination products need every ingredient identified by a pharmacist.`);
 if(!m.confirmed)gaps.push(`${m.name||'Unnamed medicine'}: details have not been confirmed against the prescription.`);
 if(!(Number(m.strength)>0)||!(Number(m.quantity)>0)||!m.schedule||!m.route||!m.form)gaps.push(`${m.name||'Unnamed medicine'}: strength, quantity, schedule, route, or form is missing.`);
 if(m.route!=='oral'||!['tablet','capsule'].includes(m.form))gaps.push(`${m.name}: dose calculation supports oral tablets or capsules only.`);
 if(catalog.includes(n)&&n!=='paracetamol')gaps.push(`${m.name}: individual dose limits are not checked.`);
 if(c.allergyStatus==='known'&&(c.allergies||'').split(/[,;\n]/).map(normalize).includes(n))add(`allergy-${m.id}`,'priority','Medicine matches a reported allergy','You listed an allergy to this ingredient. A professional needs to check the reaction and prescription.',m.name,null);
 if(n==='methotrexate'&&['1','2','3','4'].includes(m.schedule))add(`weekly-${m.id}`,'priority','Double-check the methotrexate schedule','For many inflammatory illnesses this medicine is taken once a week. A daily schedule needs prompt review; cancer treatment can use different schedules.',`${m.name}: ${m.schedule} time(s) a day`,sources.weekly);
 if(nsaids.includes(n)&&(c.kidney||c.ulcer))add(`condition-${m.id}`,'review','Your health history needs a closer look','This type of pain medicine may cause problems with kidney disease or a history of stomach ulcers.',`${m.name}; ${c.kidney?'kidney disease ':''}${c.ulcer?'stomach ulcer history':''}`,sources.nsaid);
 }
 if(c.allergyStatus==='known'){gaps.push('Only exact ingredient allergy matches are checked. Drug-family allergies and reaction severity need professional review.');if(!(c.allergies||'').trim())gaps.push('No allergy names were entered.');}
 for(const n of new Set(names))if(n&&names.filter(x=>x===n).length>1)add(`duplicate-${n}`,'review','The same ingredient appears more than once','This could be intentional or could lead to taking extra. Check both packets with a pharmacist.',n,n==='paracetamol'?sources.paracetamol:null);
 const pairs=[['warfarin','ibuprofen','priority','Higher chance of bleeding','Together these medicines can increase bleeding risk.','warfarin'],['warfarin','aspirin','priority','Higher chance of bleeding','This combination needs professional oversight because it can increase bleeding risk.','warfarin'],['warfarin','naproxen','priority','Higher chance of bleeding','This anti-inflammatory pain medicine can increase bleeding risk with warfarin.','warfarin'],['methotrexate','trimethoprim','priority','This combination needs prompt review','This antibiotic can interact with methotrexate and increase serious side effects.','methotrexate'],['methotrexate','co-trimoxazole','priority','This combination needs prompt review','This antibiotic can interact with methotrexate and increase serious side effects.','methotrexate'],['ramipril','spironolactone','review','A blood test may be needed','Together these medicines can raise potassium in the blood. Your doctor may prescribe them together with monitoring.','ramipril']];
 for(const[a,b,l,t,e,s]of pairs)if(names.includes(a)&&names.includes(b))add(`${a}-${b}`,l,t,e,`${a} + ${b}`,sources[s]);
 const pain=[...new Set(names.filter(n=>nsaids.includes(n)))];if(pain.length>1)add('nsaid-overlap','review','Similar pain medicines overlap','Taking more than one of these medicines can increase side effects, including stomach bleeding. Ask whether the combination is intended.',pain.join(' + '),sources.nsaid);
 const para=active.filter(m=>normalize(m.name)==='paracetamol');
 const calc=para.length&&para.every(m=>m.confirmed&&Number(m.strength)>0&&Number(m.quantity)>0&&['1','2','3','4'].includes(m.schedule)&&['mg','g'].includes(m.unit)&&m.route==='oral'&&['tablet','capsule'].includes(m.form));
 if(para.length&&!calc)gaps.push('Paracetamol daily total cannot be calculated from the current details.');
 if(calc){const total=para.reduce((s,m)=>s+Number(m.strength)*(m.unit==='g'?1000:1)*Number(m.quantity)*Number(m.schedule),0);if(total>4000)add('paracetamol-total','priority','Entered daily amount is above 4,000 mg',`These entries add up to ${total.toLocaleString()} mg of paracetamol in 24 hours. Too much can seriously harm the liver. If this amount has already been taken, seek urgent medical or poison-service advice even if the person feels well.`,`${para.length} paracetamol entry/entries`,sources.paracetamol);gaps.push('4,000 mg is not a personal recommended dose. Lower limits may apply; weight, liver health and other medicines need review.');}
 if(c.pregnancy)gaps.push('Pregnancy or breastfeeding reported: medicine-specific checks are unavailable.');
 if(c.liver)gaps.push('Liver disease reported: personal dose adjustments are unavailable.');
 return{version:VERSION,createdAt:new Date().toISOString(),findings:findings.sort((a,b)=>(a.level==='priority'?0:1)-(b.level==='priority'?0:1)),gaps:[...new Set(gaps)],activeCount:active.length,excludedCount:medicines.length-active.length,status:'Professional review needed — limited screening'};
}
